   647	// Each run answers with its own number and then waits at its gate, so a test decides when it ends.
   648	const gated = (runs: number) => {
   649	  const sent: OutgoingMessage[] = [];
   650	  const socket = {
   651	    readyState: WebSocket.OPEN as number,
   652	    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
   653	  };
   654	  const ws = socket as unknown as WebSocket;
   655	  const gates = Array.from({length: runs}, () => deferred());
   656	  const handed: SessionEntry[][] = [];
   657	  const processMessageStream = async function* (session: ChatSession): AsyncGenerator<MessageChunk> {
   658	    const run = handed.length;
   659	    handed.push(structuredClone(session.entries));
   660	    yield text(`answer ${run}`);
   661	    await gates[run].until;
   662	    yield STOP;
   663	  };
   664	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
   665	  const handle = createMessageHandler({processMessageStream} as unknown as ChatOrchestrator);
   666	
   667	  return {
   668	    session,
   669	    handed,
   670	    release: (run: number) => gates[run].release(),
   671	    close: () => {
   672	      socket.readyState = WebSocket.CLOSED;
   673	    },
   674	    frames: () => wire(sent),
   675	    send: (raw: unknown) => handle(ws, session, raw),
   676	  };
   677	};
